-- The sheet's pools, in the order added: a name (trimmed, at most once per sheet).
CREATE TABLE pool (
    sheet_id VARCHAR(200) NOT NULL,
    name     VARCHAR(200) NOT NULL,
    position BIGINT       NOT NULL,
    PRIMARY KEY (sheet_id, name)
);

-- A pool's members, in the order added: a person of the sheet with a share percent (more than 0.00,
-- at most 100.00). A person is in a pool at most once, and may be in several pools.
CREATE TABLE pool_member (
    sheet_id  VARCHAR(200)  NOT NULL,
    pool      VARCHAR(200)  NOT NULL,
    person_id BIGINT        NOT NULL REFERENCES person (id),
    share     DECIMAL(5,2)  NOT NULL,
    position  BIGINT        NOT NULL,
    PRIMARY KEY (sheet_id, pool, person_id)
);

CREATE TABLE asof.pool AS SELECT * FROM public.pool WHERE FALSE;
CREATE TABLE asof_hist.pool AS SELECT * FROM public.pool WHERE FALSE;
ALTER TABLE asof_hist.pool ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.pool ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.pool ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX pool_hist_sheet ON asof_hist.pool (sheet_id, h_seq);
CREATE TRIGGER pool_history AFTER INSERT, UPDATE, DELETE ON public.pool FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';

CREATE TABLE asof.pool_member AS SELECT * FROM public.pool_member WHERE FALSE;
CREATE TABLE asof_hist.pool_member AS SELECT * FROM public.pool_member WHERE FALSE;
ALTER TABLE asof_hist.pool_member ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.pool_member ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.pool_member ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX pool_member_hist_sheet ON asof_hist.pool_member (sheet_id, h_seq);
CREATE TRIGGER pool_member_history AFTER INSERT, UPDATE, DELETE ON public.pool_member FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- The sheet's pot: shared out among the members of each balanced pool by their shares. Null when
-- unset (none). Not dated.
ALTER TABLE public.sheet_setting ADD COLUMN pot DECIMAL(12,2);
ALTER TABLE asof.sheet_setting ADD COLUMN pot DECIMAL(12,2);
ALTER TABLE asof_hist.sheet_setting ADD COLUMN pot DECIMAL(12,2);
-- The history trigger keeps the column list it was created with: create it again to see the new one.
DROP TRIGGER public.sheet_setting_history;
CREATE TRIGGER sheet_setting_history AFTER INSERT, UPDATE, DELETE ON public.sheet_setting FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A person's aliases: other names they go by, kept trimmed. An alias shares the names' uniqueness on
-- its sheet (compared without case and ignoring surrounding spaces): it equals no name or alias there.
-- `alias_key` is the form they are compared in.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(500) NOT NULL,
    alias_key VARCHAR(500) NOT NULL
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

CREATE TABLE asof.person_alias AS SELECT * FROM public.person_alias WHERE FALSE;
CREATE TABLE asof_hist.person_alias AS SELECT * FROM public.person_alias WHERE FALSE;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_seq BIGINT NOT NULL;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_made_on DATE;
ALTER TABLE asof_hist.person_alias ADD COLUMN h_op CHAR(1) NOT NULL;
CREATE INDEX person_alias_hist_sheet ON asof_hist.person_alias (sheet_id, h_seq);
CREATE TRIGGER person_alias_history AFTER INSERT, UPDATE, DELETE ON public.person_alias FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A user watching a person, kept per sheet; one row per watching user, in the order they started
-- watching (a user who stops and starts again goes to the end).
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, person_id, id);
-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note to add
-- a DRAFT claim with. A claim made from one copies them, so a later change does not alter it.
CREATE TABLE claim_template (
    sheet_id VARCHAR(200)  NOT NULL,
    name     VARCHAR(200)  NOT NULL,
    amount   DECIMAL(14,2) NOT NULL,
    note     VARCHAR(2000) NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
