CREATE TRIGGER person_alias_history AFTER INSERT, UPDATE, DELETE ON public.person_alias FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A user watching a person, kept per sheet; one row per watching user, in the order they started
-- watching (a user who stops and starts again goes to the end).
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, person_id, id);
-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note to add
-- a DRAFT claim with. A claim made from one copies them, so a later change does not alter it.
CREATE TABLE claim_template (
    sheet_id VARCHAR(200)  NOT NULL,
    name     VARCHAR(200)  NOT NULL,
    amount   DECIMAL(14,2) NOT NULL,
    note     VARCHAR(2000) NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
