import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's retirement: whether they are retired and from when, and the date and button to retire
 * them (a blank date is the sheet's today). Set at all, they count as retired at once, whatever the
 * date: no claim dated after it is accepted, and the list hides them unless retired people are shown.
 */
function PersonRetire({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`, { from: date, user }),
    onSuccess: () => setFrom(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, retire.reset);
  return (
    <>
      <td data-testid="person-retired">{person.retired ? 'yes' : 'no'}</td>
      <td data-testid="person-retired-from">{person.retiredFrom ?? ''}</td>
      <td>
        <input
          type="text"
          placeholder="yyyy-mm-dd"
          data-testid="person-retire-date"
          value={from}
          onChange={(e) => {
            setFrom(e.target.value);
            retire.reset();
          }}
        />{' '}
        <button
          type="button"
          data-testid="person-retire"
          disabled={retire.isPending}
          onClick={() => {
            actionTaken();
            retire.mutate(from);
          }}
        >
          Retire
        </button>
        {retire.isError && (
          <span data-testid="person-error" role="alert">
            {' '}
            Could not retire this person.
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 30,
    Component: () => (
      <>
        <th>Retired</th>
        <th>Retired from</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 30, Component: PersonRetire }),
];
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { useClaims } from '../claims/useClaims';
import { peopleKey, usePeople, type Person } from '../people/usePeople';
import { hundredths, totalDue } from '../rates/useRates';
import { useSheetToday } from '../sheet/useSheet';

/**
 * A person's patrons: the other people on the sheet they have named (names sorted, comma and space
 * separated), and their backing, the patrons' SETTLED claims dated within the 90 days up to and
 * including the sheet's today added up, each at the due fixed when it was settled (0.00 with none). One patron is named at a time; the server refuses the person themselves and someone
 * already their patron.
 */
/** The first day (yyyy-mm-dd) of the 90 days up to and including `today`. */
function backingSince(today: string): string {
  if (today === '') return '';
  return new Date(Date.parse(`${today}T00:00:00Z`) - 89 * 86_400_000).toISOString().slice(0, 10);
}

function PersonPatrons({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const { data: people = [] } = usePeople(sheet);
  const { data: all = [] } = useClaims(sheet);
  const today = useSheetToday(sheet);
  const [chosen, setChosen] = useState('');

  const patrons = people.filter((p) => person.patrons.includes(p.id));
  const names = patrons.map((p) => p.name).sort();
  const since = backingSince(today);
  const backing = all
    .filter((c) => person.patrons.includes(c.personId) && c.status === 'SETTLED' && c.due !== null)
    .filter((c) => c.date >= since && c.date <= today)
    .reduce((sum, c) => sum + hundredths(c.due!), 0n);

  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/patrons`, { patronId, user }),
    onSuccess: () => setChosen(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
      <td data-testid="person-backing">{totalDue([backing])}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={chosen}
          onChange={(e) => {
            add.reset();
            setChosen(e.target.value);
          }}
        >
          <option value="">Choose a patron…</option>
          {people
            .filter((p) => p.id !== person.id)
            .map((p) => (
              <option key={p.id} value={String(p.id)}>
                {p.name}
              </option>
            ))}
        </select>
        <button
          type="button"
          data-testid="person-patron-add"
          disabled={add.isPending || chosen === ''}
          onClick={() => {
            add.reset();
            add.mutate(Number(chosen));
          }}
        >
          Add patron
        </button>
        {add.isError && (
          <span data-testid="person-patron-error" role="alert">
            {' '}
            Could not name this patron (not themselves, and not someone already their patron).
          </span>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumns.fill({
    order: 40,
    Component: () => (
      <>
        <th>Patrons</th>
        <th>Backing</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 40, Component: PersonPatrons }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
 *  dated within a hold count in no live total, nor any OPEN or PENDING claim of theirs once the sheet's today
 *  reaches their retirement date, unless a statement binds them. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). `terms` are
 *  the person's own terms in days (null: none), ahead of their grade's and the sheet's.
 *  `contact` is the person's contact, trimmed and lower-cased (null: none). `aliases` are the
 *  person's aliases, sorted as names are compared; the quick-add bar and the paste box find a
 *  person by an alias as well as by the name. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: { from: string; to: string | null }[];
  patrons: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
};

/** Whether the sheet's `today` (yyyy-mm-dd) has reached the person's retirement date. */
export function retiredOut(person: Person, today: string): boolean {
  return person.retiredFrom !== null && today !== '' && today >= person.retiredFrom;
}

/** Whether a claim of the person's dated `date` (yyyy-mm-dd) is held out of the live totals: the date
 *  falls within any of the person's holds, or the sheet's `today` has reached their retirement date. */
